// "Name: message" per line (also the full-width colon). Lines without a name continue the message above.
const raw = String($json.Conversation || '').replace(/\r/g, '');
const messages = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (!t) continue;
  const m = t.match(/^([^:：]{1,40})[:：]\s*(.+)$/);
  if (m && !/^https?$/i.test(m[1])) messages.push({ who: m[1].trim(), text: m[2].trim(), time: '' });
  else if (messages.length) messages[messages.length - 1].text += '\n' + t;
  else messages.push({ who: '(unknown)', text: t, time: '' });
}
return [{ json: { source: 'form', purpose: String($json.Purpose || '').trim(), messages, where: 'pasted conversation' } }];

// The mention must be inside a thread; the text after the mention says what the slides are for.
const ev = $json.event || $json;
if (ev.bot_id) return [];
const allowed = String($json.allowed_slack_users || '').split(',').map((s) => s.trim()).filter(Boolean);
const appMention = (String(ev.text || '').match(/<@[A-Z0-9]+>/) || [''])[0]; // the app's own mention, to leave earlier requests out of the conversation
const base = { source: 'slack', channel: ev.channel, thread_ts: ev.thread_ts || ev.ts, mention_ts: ev.ts, app_mention: appMention };
let text = '';
if (!allowed.includes(ev.user)) text = 'Sorry, you are not on the list of people who can use this.';
else if (!ev.thread_ts) text = 'Mention me inside a thread (reply to the conversation), and I will turn that thread into slides.';
// the words after the mention, without Slack formatting marks
const purpose = String(ev.text || '').replace(/<@[^>]+>/g, ' ').replace(/[*_~`]/g, '').replace(/\s+/g, ' ').trim();
return [{ json: { ok: !text, text, purpose, ...base } }];

// One item per person who wrote in the thread (bots and the mention itself are left out later).
const ids = [...new Set($input.all().map((i) => i.json.user).filter(Boolean))];
return ids.map((user) => ({ json: { user } }));

// Names come from users.info (needs the users:read scope). Without it, people are shown as Member A, B, ...
const m = $('Read the Slack mention').first().json;
const people = $('List the people').all().map((i) => i.json.user);
const names = {};
$input.all().forEach((i, k) => {
  const u = i.json.user;
  const name = i.json.ok && u ? (u.profile && (u.profile.display_name || u.profile.real_name)) || u.real_name || u.name : null;
  names[people[k]] = name || 'Member ' + String.fromCharCode(65 + k);
});
const messages = $('Read the thread').all().map((i) => i.json)
  .filter((x) => !x.bot_id && x.ts !== m.mention_ts && String(x.text || '').trim() && !(m.app_mention && String(x.text).includes(m.app_mention)))
  .map((x) => ({ who: names[x.user] || 'Unknown', text: String(x.text).replace(/<@([A-Z0-9]+)>/g, (s, id) => '@' + (names[id] || id)), ts: Number(x.ts) }));
return [{ json: { source: 'slack', purpose: m.purpose, messages, channel: m.channel, thread_ts: m.thread_ts, where: 'Slack thread' } }];

// Numbered transcript for Claude. Too short a conversation is stopped here.
const c = $json;
// Slack times are shown in the Config time zone
const msgs = (c.messages || []).slice(-Number(c.max_messages)).map((m) => ({ who: m.who, text: m.text, time: m.ts ? DateTime.fromSeconds(m.ts).setZone(c.timezone).toFormat('yyyy-MM-dd HH:mm') : m.time || '' }));
if (msgs.length < 2) return [{ json: { ok: false, problem: 'There are fewer than 2 messages to work from.' } }];
const transcript = msgs.map((m, i) => '[' + (i + 1) + '] ' + m.who + (m.time ? ' (' + m.time + ')' : '') + ': ' + m.text.replace(/\n/g, ' / ')).join('\n');
const note = (c.messages || []).length > msgs.length ? 'Only the last ' + msgs.length + ' messages were used.' : '';
return [{ json: { ok: true, messages: msgs, transcript, purpose: c.purpose || c.default_purpose, note } }];

// Every item must quote a message that really says it, and every number or date in it must be written in that message.
const p = $('Prepare the prompt').first().json;
const cfg = $('Config').first().json;
const msgs = p.messages;
const norm = (s) => String(s ?? '').normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').replace(/[「」『』"“”'’]/g, '').trim();
const digits = (s) => String(s ?? '').normalize('NFKC').match(/\d+/g) || [];
const hasNum = (text, t) => new RegExp('(^|\\D)0*' + Number(t) + '(\\D|$)').test(String(text).normalize('NFKC'));
let b;
try { b = JSON.parse(String($json.text ?? '').match(/\{[\s\S]*\}/)[0]); }
catch (e) { return [{ json: { ok: false, problem: 'Could not read the AI answer as JSON. Try again.' } }]; }
const dropped = [];
const used = new Map();
function findMsg(s) {
  const q = norm(s && s.quote);
  if (q.length < 3) return null;
  const k = Number(s.msg) - 1;
  if (msgs[k] && norm(msgs[k].text).includes(q)) return k;
  const other = msgs.findIndex((m) => norm(m.text).includes(q));
  return other >= 0 ? other : null;
}
function check(section, it, fields) {
  const main = fields[0];
  const label = fields.map((f) => it[f]).filter(Boolean).join(' / ');
  const srcs = Array.isArray(it.sources) ? it.sources : it.quote ? [{ quote: it.quote, msg: it.msg }] : [];
  const ks = srcs.map(findMsg);
  if (!ks.length || ks.some((k) => k === null)) { dropped.push(section + ': "' + label + '" (a quote it gives is not in the conversation)'); return null; }
  const where = [...new Set(ks)].sort((a, b) => a - b);
  const src = where.map((k) => msgs[k].text).join('\n');
  const nums = where.map((k) => k + 1).join(', ');
  const bad = digits(it[main]).filter((t) => !hasNum(src, t));
  if (bad.length) { dropped.push(section + ': "' + label + '" (' + bad.join(', ') + ' is not in message ' + nums + ')'); return null; }
  const out = { ...it, refs: where.map((k) => k + 1) };
  if (it.due && (digits(it.due).length ? digits(it.due).some((t) => !hasNum(src, t)) : !norm(src).includes(norm(it.due)))) {
    dropped.push(section + ': the due date "' + it.due + '" of "' + it[main] + '" (not written in message ' + nums + ')'); out.due = null;
  }
  if (it.owner) {
    const o = norm(it.owner);
    const named = msgs.some((m) => norm(m.who) === o) || norm(src).includes(o);
    if (!named) { dropped.push(section + ': the owner "' + it.owner + '" of "' + it[main] + '" (not a person in the conversation)'); out.owner = null; }
  }
  srcs.forEach((s, i) => { if (!used.has(ks[i])) used.set(ks[i], String(s.quote || '').trim()); });
  return out;
}
const max = Number(cfg.max_items);
const pick = (section, list, fields) => (Array.isArray(list) ? list : []).slice(0, max).map((it) => check(section, it, fields)).filter(Boolean);
const background = pick('Background', b.background, ['text']);
const points = pick('Discussion points', b.points, ['text']);
const decisions = pick('Decisions needed', b.decisions, ['text']);
const next = pick('Next steps', b.next_steps, ['task']);
if (!background.length && !points.length && !decisions.length && !next.length) return [{ json: { ok: false, problem: 'Nothing in the AI draft could be traced back to the conversation, so no slides were made.' + (dropped.length ? ' Dropped: ' + dropped.slice(0, 3).join('; ') : '') } }];
let title = String(b.title || '').trim();
if (!title || digits(title).some((t) => !msgs.some((m) => hasNum(m.text, t)))) title = 'Meeting brief';
const ref = (x) => ' [' + x.refs.join(', ') + ']';
const bullets = (arr) => (arr.length ? arr.map((x) => '• ' + x.text + ref(x)).join('\n') : '(nothing in the conversation)');
const today = DateTime.now().setZone($('Config').first().json.timezone);
const values = {
  title,
  subtitle: (p.purpose ? p.purpose + '\n' : '') + 'From a ' + ($('Config').first().json.where || 'conversation') + ' (' + msgs.length + ' messages) · ' + today.toFormat('yyyy-MM-dd'),
  background: bullets(background), points: bullets(points), decisions: bullets(decisions),
  next_steps: next.length ? next.map((x) => '• ' + x.task + (x.owner ? ' — ' + x.owner : ' — (owner not stated)') + (x.due ? ', ' + x.due : '') + ref(x)).join('\n') : '(nothing in the conversation)',
  sources: [...used.keys()].sort((a, c) => a - c).map((k) => '[' + (k + 1) + '] ' + msgs[k].who + (msgs[k].time ? ' (' + msgs[k].time + ')' : '') + ': "' + used.get(k) + '"').join('\n'),
};
const requests = Object.entries(values).map(([k, v]) => ({ replaceAllText: { containsText: { text: '{{' + k + '}}', matchCase: true }, replaceText: String(v) } }));
const counts = { background: background.length, points: points.length, decisions: decisions.length, next_steps: next.length };
return [{ json: { ok: true, values, requests, dropped, counts, note: p.note, file_name: 'Brief ' + today.toFormat('yyyy-MM-dd') + ' ' + title.slice(0, 60) } }];

const labels = { 'Read the thread': 'reading the Slack thread', 'Copy the template': 'copying the Slides template', 'Fill in the slides': 'filling in the slides' };
const node = $prevNode.name;
const err = $json.error && ($json.error.message || $json.error);
return [{ json: { problem: 'An error came back while ' + (labels[node] || node) + (err ? ' (' + String(err).slice(0, 200) + ')' : '') + '.' + (node === 'Fill in the slides' ? ' An unfinished copy of the template is left in Google Drive; delete it.' : '') } }];

// Reply in the thread: the link, what went into the slides, and what was left out and why.
const m = $('Read the Slack mention').first().json;
let text;
if ($json.problem) text = 'No slides were made. ' + $json.problem;
else {
  const b = $('Check the brief').all(0)[0].json;
  const url = 'https://docs.google.com/presentation/d/' + $('Copy the template').all(0)[0].json.id + '/edit';
  const c = b.counts;
  text = '*Slides ready:* <' + url + '|' + b.values.title + '>\n' + c.background + ' background, ' + c.points + ' discussion points, ' + c.decisions + ' decisions, ' + c.next_steps + ' next steps. Each item shows the message number it came from.'
    + (b.dropped.length ? '\n*Left out* (could not be traced to the conversation):\n' + b.dropped.slice(0, 8).map((d) => '• ' + d).join('\n') : '')
    + (b.note ? '\n' + b.note : '') + '\nCheck the slides before you share them.';
}
return [{ json: { channel: m.channel, thread_ts: m.thread_ts, text } }];
